mapper.select:
SELECT DATE(create_time) AS createTime, IFNULL(fqc_quantity_instock, 0) AS uncheckedTotal, IFNULL(fqc_daily_input, 0) AS fqcDailyInput, COALESCE(( SELECT SUM(COALESCE(ar.finish_data, 0)) FROM fqc_attendance_record ar WHERE ar.record_date = DATE(fqc_display.create_time) AND ar.is_deleted = 0 AND ar.emp_team <> 'HV' ), 0) AS fqcFunctionTestOutput, IFNULL(fqc_function_undistributed, 0) AS uncertifiedTotal, IFNULL(fqc_daily_output, 0) AS fqcDailyOutput, IFNULL(fqc_withstand_undistributed, 0) AS fqcWithstandUndistributed, GREATEST(IFNULL(fqc_daily_input, 0) - IFNULL(fqc_withstand_undistributed, 0),0) AS fqcAllocated, update_time AS updateTime FROM fqc_display
(is_deleted = 0 OR is_deleted IS NULL)
AND ( fqc_daily_input LIKE CONCAT('%', #{queryParams.keywords}, '%') OR fqc_daily_output LIKE CONCAT('%', #{queryParams.keywords}, '%') OR fqc_quantity_instock LIKE CONCAT('%', #{queryParams.keywords}, '%') OR fqc_withstand_undistributed LIKE CONCAT('%', #{queryParams.keywords}, '%') OR fqc_function_undistributed LIKE CONCAT('%', #{queryParams.keywords}, '%') )
AND DATE(create_time) >= #{queryParams.createTimeStart}
AND DATE(create_time) <= #{queryParams.createTimeEnd}
AND DATE(update_time) >= #{queryParams.updateTimeStart}
AND DATE(update_time) <= #{queryParams.updateTimeEnd}
ORDER BY create_time DESC
